/bin/zsh -lc "node - <<'NODE'
const fs=require('fs');
const j=JSON.parse(fs.readFileSync('out/skills-gap.json','utf8'));
const svg=fs.readFileSync('out/skills-gap-card.svg','utf8');
const labels=['Research verification','Spreadsheet work','Visual design','Coding','Writing','Tool execution'];
const allowed=new Set(['Critical','Weak','Developing','Covered','Not measured']);
const checks={schema:j.schemaVersion==='agent-skills-gap/0.1',sixCategories:labels.every(x=>j.categories.some(c=>c.label===x&&allowed.has(c.level))),underTwoNotMeasured:j.categories.filter(c=>c.tasks<2).every(c=>c.level==='Not measured'),recommendationCap:j.recommended.length<=7,svgDimensions:/width=\"1200\" height=\"630\"/.test(svg),allCategoriesOnCard:labels.every(x=>svg.includes(x)),noBranding:"'!/(EDGE|getedge'"\\.cc)/i.test(svg)};
console.log(JSON.stringify(checks,null,2));
if(Object.values(checks).some(v=>"'!v)) process.exit(1);
NODE'

